<script setup lang="ts">
import { computed, onMounted, onUnmounted, provide, ref } from 'vue'
import SearchBar from './components/SearchBar.vue'
import MonitorSidebar from './components/MonitorSidebar.vue'
import MetricGrid from './components/MetricGrid.vue'
import FocusMetricPanel from './components/FocusMetricPanel.vue'
import FocusSettingsModal from './components/FocusSettingsModal.vue'
import TrendPanel from './components/TrendPanel.vue'
import ImageFallback from './components/ImageFallback.vue'
import ExportModal from './components/ExportModal.vue'
import CollectionLogModal from './components/CollectionLogModal.vue'
import bilibiliLogo from './assets/bilibili-logo.svg'
import type { MetricKey, Target, TrendRange } from './types'

type ViewState='empty'|'searching'|'preview'|'viewing'|'monitoring'|'history'|'error'
const query=ref(''),targets=ref<Target[]>([]),history=ref<Target[]>([]),selected=ref<Target|null>(null),preview=ref<any>(null),trend=ref<any>(null),error=ref(''),loading=ref(false),state=ref<ViewState>('empty'),range=ref<TrendRange>(168),mode=ref<'growth'|'total'>('growth'),metric=ref<MetricKey>('view_count'),showSettings=ref(false),interval=ref(60),summary=ref<any>(null),showExport=ref(false),exportAllScope=ref(false),exporting=ref(false),showLogs=ref(false),logs=ref<any[]>([]),logsLoading=ref(false),detailMode=ref<'all'|'focus'>('all'),showFocusSettings=ref(false),focusSaving=ref(false)
const isVideo=computed(()=>selected.value?.target_type==='video')
provide('trendRange', range)
const fallbackMetric=computed<MetricKey>(()=>isVideo.value?'view_count':'follower_count')
async function api(path:string,options?:RequestInit){const response=await fetch(path,options);const data=await response.json();if(!response.ok)throw Error(data.detail||'请求失败');return data}
async function load(){[targets.value,history.value,summary.value]=await Promise.all([api('/api/targets'),api('/api/targets/history'),api('/api/system/summary')])}
async function search(){if(!query.value.trim())return;loading.value=true;state.value='searching';error.value='';try{preview.value=await api('/api/targets/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({value:query.value})});state.value='preview'}catch(e:any){error.value=e.message;state.value='error'}finally{loading.value=false}}
async function startMonitoring(){if(!preview.value)return;loading.value=true;try{const target=await api('/api/targets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...preview.value,interval_seconds:60})});preview.value=null;await load();selected.value=targets.value.find(x=>x.id===target.id)||target;state.value='monitoring';setMetric();await refresh()}catch(e:any){error.value=e.message;state.value='error'}finally{loading.value=false}}
async function viewOnce(){if(!preview.value)return;loading.value=true;try{const data=await api('/api/targets/view-once',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...preview.value,interval_seconds:60})});selected.value={...preview.value,id:0,active:false,last_error:'',interval_seconds:60};preview.value=null;trend.value={points:[{time:new Date().toISOString(),...data.stats}],latest:{time:new Date().toISOString(),...data.stats},growth:{}};state.value='viewing';setMetric()}catch(e:any){error.value=e.message;state.value='error'}finally{loading.value=false}}
function setMetric(){metric.value=fallbackMetric.value}
async function refresh(){if(!selected.value||selected.value.id===0)return;try{const group=selected.value.target_type==='video'?'videos':'uploaders';trend.value=await api(`/api/${group}/${selected.value.id}/trend?hours=${range.value}`)}catch(e:any){error.value=e.message;state.value='error'}}
async function changeRange(value:TrendRange){range.value=value;await refresh()}
async function select(target:Target){selected.value=target;state.value=target.active?'monitoring':'history';setMetric();await refresh()}
async function restore(target:Target){loading.value=true;try{const active=await api('/api/targets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({target_type:target.target_type,target_key:target.target_key,interval_seconds:60})});await load();await select(active)}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function remove(target:Target){if(!window.confirm(`确定停止监控“${target.title||target.target_key}”吗？\n\n历史数据不会删除。`))return;await api(`/api/targets/${target.id}`,{method:'DELETE'});if(selected.value?.id===target.id){selected.value=null;trend.value=null;state.value=targets.value.length?'monitoring':'empty'}await load()}
async function collectNow(){if(!selected.value||selected.value.id===0)return;loading.value=true;try{const result=await api(`/api/targets/${selected.value.id}/collect`,{method:'POST'});selected.value=result.target;await load();await refresh()}catch(e:any){error.value=e.message;state.value='error'}finally{loading.value=false}}
async function saveSettings(){if(!selected.value)return;try{selected.value=await api(`/api/targets/${selected.value.id}/settings`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({interval_seconds:Number(interval.value)})});showSettings.value=false}catch(e:any){error.value=e.message}}
async function saveFocusMetrics(metrics:string[]){if(!selected.value||!selected.value.id)return;focusSaving.value=true;try{const updated=await api(`/api/targets/${selected.value.id}/focus`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({metrics})});selected.value=updated;await load();showFocusSettings.value=false}catch(e:any){error.value=e.message}finally{focusSaving.value=false}}
function openExport(all:boolean){if(!all&&(!selected.value||selected.value.id===0))return;exportAllScope.value=all;showExport.value=true}
async function exportData(options:{format:'csv'|'json';hours:'all'|'24'|'168'|'720'}){if(!exportAllScope.value&&(!selected.value||selected.value.id===0))return;exporting.value=true;try{const base=exportAllScope.value?'/api/exports':`/api/exports/targets/${selected.value!.id}`;const response=await fetch(`${base}?format=${options.format}&hours=${options.hours}`);if(!response.ok){const data=await response.json();throw Error(data.detail||'导出失败')}const blob=await response.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=exportAllScope.value?`bilibili-monitor-all.${options.format}`:`bilibili-monitor-${selected.value!.id}.${options.format}`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);showExport.value=false}catch(e:any){error.value=e.message;state.value='error'}finally{exporting.value=false}}
async function openLogs(){if(!selected.value||selected.value.id===0)return;showLogs.value=true;logsLoading.value=true;try{logs.value=await api(`/api/targets/${selected.value.id}/logs?limit=20`)}catch(e:any){error.value=e.message;state.value='error'}finally{logsLoading.value=false}}
let timer:any;onMounted(async()=>{await load();if(targets.value.length){state.value='monitoring';await select(targets.value[0])}timer=setInterval(()=>{if(selected.value?.active)refresh()},60000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><main class="app-shell" :class="{'focus-active':detailMode==='focus'}"><header class="topbar"><div class="brand"><div class="brand-mark"><img :src="bilibiliLogo" alt="哔哩哔哩"/></div><div><strong>BilibiliMonitor</strong><span>{{detailMode==='focus'?'专注数据视图':'轻量数据观察工作台'}}</span></div></div><SearchBar v-if="detailMode!=='focus'" v-model:value="query" :loading="loading" @search="search"/><div class="top-status"><i></i>{{detailMode==='focus'?'仅显示当前对象':'本地运行'}}</div></header><div v-if="state==='error'&&error" class="error-banner"><span>{{error}}</span><button class="soft-button" @click="state=selected?'monitoring':'empty';error=''">关闭</button></div><section v-if="state==='empty'&&!targets.length&&!history.length" class="empty-home"><div class="hero-orb">◎</div><span class="eyebrow">BILIBILI DATA WORKSPACE</span><h1>从一个视频或 UP 主开始</h1><p>搜索后选择是否加入监控，所有历史快照保存在本地。</p></section><section v-else class="workspace" :class="{'focus-workspace':detailMode==='focus'}"><MonitorSidebar v-if="detailMode!=='focus'" :targets="targets" :history="history" :selected="selected" :summary="summary" @select="select" @remove="remove" @restore="restore" @export-all="openExport(true)"/><article v-if="selected" class="detail" :class="{'focus-detail':detailMode==='focus'}"><div class="detail-head"><div class="identity"><h1>{{selected.title||selected.target_key}}</h1><p>{{detailMode==='focus'?'专注模式 · 仅显示已选指标':isVideo?'视频互动数据与播放走势':'账号粉丝与投稿变化趋势'}}</p></div><div v-if="detailMode==='focus'" class="identity-actions"><span v-if="selected.active" class="live-badge"><i></i>自动监控中</span><span v-else class="history-badge">历史记录</span><button class="soft-button" @click="detailMode='all'">返回全部指标</button></div><div v-else class="identity-actions"><span v-if="selected.active" class="live-badge"><i></i>自动监控中</span><span v-else class="history-badge">历史记录</span><a :href="isVideo?`https://www.bilibili.com/video/${selected.target_key}`:`https://space.bilibili.com/${selected.target_key}`" target="_blank">打开 B 站 ↗</a></div></div><div v-if="detailMode==='all'" class="detail-view-switch segmented"><button class="selected">全部指标</button><button @click="detailMode='focus'">专注模式</button></div><MetricGrid v-if="detailMode==='all'" :target="selected" :latest="trend?.latest" :growth="trend?.growth"/><FocusMetricPanel v-else :target="selected" :latest="trend?.latest" :growth="trend?.growth" @configure="showFocusSettings=true"/><div v-if="detailMode==='all'" class="control-bar"><div class="control-main"><button v-if="selected.active" class="primary-button" @click="collectNow">{{loading?'采集中…':'立即采集'}}</button><button v-if="selected.active" class="soft-button" @click="showSettings=true">采集设置</button><button v-if="selected.id" class="soft-button" @click="openExport(false)">导出数据</button><button v-if="selected.id" class="soft-button" @click="openLogs">采集记录</button><span class="updated">最近成功：{{selected.last_success_at?new Date(selected.last_success_at).toLocaleString('zh-CN'):'暂无'}}</span></div><span v-if="selected.last_error" class="failure">{{selected.last_error}}</span></div><TrendPanel v-if="detailMode==='all'" :target="selected" :trend="trend" :range="range" :metric="metric" :mode="mode" @update:range="changeRange" @update:metric="metric=$event" @update:mode="mode=$event"/></article></section><div v-if="preview" class="modal-backdrop"><div class="preview-modal"><div class="preview-top"><span class="type-badge">{{preview.target_type==='video'?'视频':'UP 主'}}</span><button class="modal-close icon-button" @click="preview=null">×</button></div><ImageFallback :src="preview.cover_url" class="preview-cover" :kind="preview.target_type==='video'?'cover':'avatar'" :alt="preview.title"/><div class="preview-info"><h2>{{preview.title||preview.target_key}}</h2><p>{{preview.target_key}}</p><small>{{preview.description||'已找到公开信息，可以选择查看或加入监控。'}}</small></div><div class="modal-actions"><button class="soft-button" @click="viewOnce">仅查看一次</button><button class="primary-button" @click="startMonitoring">开始监控</button></div></div></div><div v-if="showSettings" class="modal-backdrop"><div class="settings-modal"><button class="modal-close icon-button" @click="showSettings=false">×</button><span class="eyebrow">COLLECTION SETTINGS</span><h2>采集设置</h2><p>设置后台自动采集频率，最短间隔为 60 秒。</p><input v-model.number="interval" type="number" min="60" step="60"/><div class="modal-actions"><button class="soft-button" @click="showSettings=false">取消</button><button class="primary-button" @click="saveSettings">保存设置</button></div></div></div><FocusSettingsModal v-if="showFocusSettings&&selected" :target="selected" :saving="focusSaving" @close="showFocusSettings=false" @save="saveFocusMetrics"/><ExportModal v-if="showExport" :target="selected" :all="exportAllScope" :exporting="exporting" @close="showExport=false" @export="exportData"/><CollectionLogModal v-if="showLogs&&selected" :target="selected" :logs="logs" :loading="logsLoading" @close="showLogs=false"/></main></template>
